-- EL-002 Older adult paying crypto exchanges, gift card sellers or money transmitters repeatedly
SELECT 'EL-002' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b ON b.customer_id = a.customer_id AND b.ts <= a.ts AND b.ts > a.ts - 1209600
WHERE (a.customer_age >= 60 AND a.direction = 'out' AND a.counterparty_type IN ('crypto_exchange', 'gift_card_merchant', 'money_transmitter')) AND (b.customer_age >= 60 AND b.direction = 'out' AND b.counterparty_type IN ('crypto_exchange', 'gift_card_merchant', 'money_transmitter'))
GROUP BY a.id
HAVING (COUNT(*) >= 3 AND SUM(b.amount_cents) >= 500000);
